// Riddle Rush bank. Read the riddle and type the answer.
// Every riddle has a hint (shown after 12 s), an explanation (shown after the round) and a
// difficulty. Answers are unique across the bank and ≤ 3 words; `alt` lists other answers
// that genuinely fit. Matching ignores case, spaces and punctuation and forgives a small typo
// (see riddleRushLogic.judgeGuess). Emoji riddles join two pictures into one word.
// Tests: riddles.test.ts. Fact-checked October 2026.

export type RiddleDifficulty = 'easy' | 'tricky' | 'genius';
export type RiddleKind = 'word' | 'emoji';

export interface Riddle {
  q: string;
  answer: string;
  alt?: string[];
  /** Shown 12 s into the round. */
  hint: string;
  /** Shown after the round: why the answer fits. */
  explanation: string;
  difficulty: RiddleDifficulty;
  kind: RiddleKind;
}

const D = { e: 'easy', t: 'tricky', g: 'genius' } as const;
const w = (d: keyof typeof D, q: string, answer: string, hint: string, explanation: string, alt?: string[]): Riddle =>
  ({ q, answer, hint, explanation, difficulty: D[d], kind: 'word', ...(alt ? { alt } : {}) });
const em = (d: keyof typeof D, pics: string, answer: string, hint: string, explanation: string, alt?: string[]): Riddle =>
  ({ q: `What am I? ${pics}`, answer, hint, explanation, difficulty: D[d], kind: 'emoji', ...(alt ? { alt } : {}) });

